// === NIVEL 1: Clase base ===
public abstract class Persona {
    protected String nombre;
    protected String email;
    protected int edad;

    public Persona(String nombre, String email, int edad) {
        this.nombre = nombre;
        this.email = email;
        this.edad = edad;
    }

    public String getNombre() { return nombre; }
    public String getEmail() { return email; }
    public int getEdad() { return edad; }

    public abstract String getRol();

    @Override
    public String toString() {
        return getRol() + ": " + nombre + " (" + email + ")";
    }
}

// === NIVEL 2: Empleado y Alumno ===
public abstract class Empleado extends Persona {
    protected double salarioBase;
    protected Departamento departamento; // COMPOSICION

    public Empleado(String nombre, String email, int edad, double salario, Departamento dept) {
        super(nombre, email, edad);
        this.salarioBase = salario;
        this.departamento = dept;
    }

    public abstract double calcularSalario();

    @Override
    public String getRol() { return "Empleado"; }

    public String getInfo() {
        return toString() + " | Dept: " + departamento.getNombre()
             + " | Salario: " + String.format("%.2f", calcularSalario());
    }
}

public class Alumno extends Persona {
    private HistorialAcademico historial; // COMPOSICION
    private Direccion direccion;           // COMPOSICION

    public Alumno(String nombre, String email, int edad, Direccion dir) {
        super(nombre, email, edad);
        this.historial = new HistorialAcademico();
        this.direccion = dir;
    }

    public void addNota(double nota) { historial.addNota(nota); }
    public double getNotaMedia() { return historial.getMedia(); }
    public Direccion getDireccion() { return direccion; }
    public HistorialAcademico getHistorial() { return historial; }

    @Override
    public String getRol() { return "Alumno"; }
}

// === NIVEL 3: Subtipes de Empleado ===
public class Profesor extends Empleado {
    private String especialidad;

    public Profesor(String n, String e, int ed, double s, Departamento d, String esp) {
        super(n, e, ed, s, d);
        this.especialidad = esp;
    }

    public String getEspecialidad() { return especialidad; }

    @Override
    public double calcularSalario() { return salarioBase; }

    @Override
    public String getRol() { return "Profesor"; }
}

public class Administrativo extends Empleado {
    private String categoria;

    public Administrativo(String n, String e, int ed, double s, Departamento d, String cat) {
        super(n, e, ed, s, d);
        this.categoria = cat;
    }

    @Override
    public double calcularSalario() {
        double extra = categoria.equals("Senior") ? 300 : 0;
        return salarioBase + extra;
    }

    @Override
    public String getRol() { return "Administrativo"; }
}

public class Departamento {
    private String nombre;
    private int capacidad;
    private Profesor director; // COMPOSICION: el departamento tiene un director

    public Departamento(String nombre, int capacidad) {
        this.nombre = nombre;
        this.capacidad = capacidad;
    }

    public String getNombre() { return nombre; }
    public int getCapacidad() { return capacidad; }
    public void setDirector(Profesor d) { this.director = d; }
    public Profesor getDirector() { return director; }

    @Override
    public String toString() { return nombre; }
}

public class Direccion {
    private String calle;
    private String ciudad;
    private String codigoPostal;

    public Direccion(String calle, String ciudad, String codigoPostal) {
        this.calle = calle;
        this.ciudad = ciudad;
        this.codigoPostal = codigoPostal;
    }

    @Override
    public String toString() {
        return calle + ", " + ciudad + " (" + codigoPostal + ")";
    }
}

import java.util.ArrayList;
import java.util.List;

public class HistorialAcademico {
    private List<Double> notas = new ArrayList<>();
    private List<String> asignaturas = new ArrayList<>();

    public void addNota(double nota) { notas.add(nota); }
    public void addAsignatura(String asig) { asignaturas.add(asig); }

    public double getMedia() {
        if (notas.isEmpty()) return 0;
        return notas.stream().mapToDouble(Double::doubleValue).average().orElse(0);
    }

    public int getNumNotas() { return notas.size(); }
    public List<Double> getNotas() { return new ArrayList<>(notas); }
    public List<String>getAsignaturas() { return new ArrayList<>(asignaturas); }

    public String getResumen() {
        return "Notas: " + getNumNotas() + " | Media: " + String.format("%.1f", getMedia());
    }
}

public class Instituto {
    private String nombre;
    private List<Departamento> departamentos = new ArrayList<>();
    private List<Alumno> alumnos = new ArrayList<>();
    private List<Empleado> empleados = new ArrayList<>();

    public Instituto(String nombre) { this.nombre = nombre; }

    public void addDepartamento(Departamento d) { departamentos.add(d); }
    public void addAlumno(Alumno a) { alumnos.add(a); }
    public void addEmpleado(Empleado e) { empleados.add(e); }

    public double getGastoTotalSalarios() {
        return empleados.stream().mapToDouble(Empleado::calcularSalario).sum();
    }

    public Alumno getMejorAlumno() {
        return alumnos.stream()
            .max(Comparator.comparingDouble(Alumno::getNotaMedia))
            .orElse(null);
    }

    public void mostrarInforme() {
        System.out.println("=== INFORME: " + nombre + " ===");
        System.out.println("\n--- Departamentos ---");
        for (Departamento d : departamentos) {
            System.out.println("  " + d + (d.getDirector() != null ? " (Dir: " + d.getDirector().getNombre() + ")" : ""));
        }
        System.out.println("\n--- Empleados ---");
        for (Empleado e : empleados) {
            System.out.println("  " + e.getInfo());
        }
        System.out.printf("\nGasto total salarios: %.2f EUR%n", getGastoTotalSalarios());
        System.out.println("\n--- Alumnos ---");
        for (Alumno a : alumnos) {
            System.out.printf("  %s | Media: %.1f%n", a.getNombre(), a.getNotaMedia());
        }
        Alumno mejor = getMejorAlumno();
        if (mejor != null) {
            System.out.println("\nMejor alumno: " + mejor.getNombre()
                 + " (" + String.format("%.1f", mejor.getNotaMedia()) + ")");
        }
    }

    public static void main(String[] args) {
        // Crear departamento
        Departamento info = new Departamento("Informatica", 30);

        // Crear empleados
        Profesor prof1 = new Profesor("Garcia", "garcia@ies.es", 45, 2200, info, "Java");
        info.setDirector(prof1);
        Administrativo admin = new Administrativo("Lopez", "lopez@ies.es", 40, 1600, info, "Senior");

        // Crear alumnos
        Alumno a1 = new Alumno("Ana", "ana@email.com", 20, new Direccion("Calle Mayor", "Sevilla", "41001"));
        a1.addNota(8.5); a1.addNota(7.0);
        Alumno a2 = new Alumno("Carlos", "carlos@email.com", 19, new Direccion("Avda. Libertad", "Malaga", "29001"));
        a2.addNota(9.2); a2.addNota(8.8);

        // Montar instituto
        Instituto ies = new Instituto("IES Tecnologia");
        ies.addDepartamento(info);
        ies.addEmpleado(prof1);
        ies.addEmpleado(admin);
        ies.addAlumno(a1);
        ies.addAlumno(a2);

        ies.mostrarInforme();
    }
}

