public interface Vendible {
    double getPrecio();
    String getDescripcion();
}

public abstract class Producto implements Vendible {
    protected String nombre;
    protected double precio;
    public Producto(String n, double p) { this.nombre = n; this.precio = p; }
    @Override public double getPrecio() { return precio; }
}

public class ProductoFisico extends Producto {
    private double pesoKg;
    public ProductoFisico(String n, double p, double peso) { super(n, p); this.pesoKg = peso; }
    @Override public String getDescripcion() { return nombre + " (" + pesoKg + "kg) - " + precio + " EUR"; }
}

public class ProductoDigital extends Producto {
    private double tamanioMB;
    private String formato;
    public ProductoDigital(String n, double p, double tMB, String f) { super(n, p); this.tamanioMB = tMB; this.formato = f; }
    @Override public String getDescripcion() { return nombre + " (" + tamanioMB + "MB, " + formato + ") - " + precio + " EUR"; }
}

public class Tienda {
    private String nombre;
    private List<Vendible> catalogo = new ArrayList<>();
    public Tienda(String n) { this.nombre = n; }
    public void addProducto(Vendible p) { catalogo.add(p); }
    public void mostrarCatalogo() {
        System.out.println("Catalogo de " + nombre + ":");
        for (Vendible v : catalogo) System.out.println("  " + v.getDescripcion());
    }
    public double getPrecioTotal() {
        return catalogo.stream().mapToDouble(Vendible::getPrecio).sum();
    }
}

