/**
 * Clase que representa un alumno en el sistema de gestion escolar.
 * 
 * <p>Un Alumno tiene nombre, email y nota media. Permite calcular
 * su calificacion y comprobar si esta aprobado.</p>
 * 
 * <p>Esta clase forma parte de la jerarquia de personas del sistema:
 * {@code Persona → Alumno}.</p>
 * 
 * @author Profesor de Programacion
 * @version 2.0
 * @since 1.0
 * @see Persona
 * @see AlumnoBecario
 */
public class Alumno extends Persona {

    /** Nota minima para estar aprobado */
    public static final double NOTA_APROBADO = 5.0;

    /** Nota maxima posible */
    public static final double NOTA_MAXIMA = 10.0;

    /** Media academica del alumno (0.0 a 10.0) */
    private double notaMedia;

    /**
     * Constructor de la clase Alumno.
     * 
     * @param nombre nombre completo del alumno (no puede estar vacio)
     * @param email direccion de correo electronico (debe contener @)
     * @param edad edad del alumno (debe ser mayor que 0)
     * @throws IllegalArgumentException si el nombre esta vacio,
     *         el email no es valido o la edad no es positiva
     */
    public Alumno(String nombre, String email, int edad) {
        super(nombre, email, edad);
        this.notaMedia = 0.0;
    }

    /**
     * Obtiene la nota media del alumno.
     * 
     * @return la nota media, un valor entre {@value #NOTA_MINIMA} y {@value #NOTA_MAXIMA}
     */
    public double getNotaMedia() {
        return notaMedia;
    }

    /**
     * Establece la nota media del alumno.
     * 
     * @param notaMedia nueva nota media (debe estar entre 0.0 y 10.0)
     * @throws IllegalArgumentException si la nota no esta en el rango valido
     */
    public void setNotaMedia(double notaMedia) {
        if (notaMedia < 0 || notaMedia > 10) {
            throw new IllegalArgumentException(
                "La nota debe estar entre 0 y 10. Valor recibido: " + notaMedia
            );
        }
        this.notaMedia = notaMedia;
    }

    /**
     * Comprueba si el alumno esta aprobado.
     * 
     * @return {@code true} si la nota media es mayor o igual a {@value #NOTA_APROBADO},
     *         {@code false} en caso contrario
     */
    public boolean estaAprobado() {
        return notaMedia >= NOTA_APROBADO;
    }

    /**
     * Obtiene la calificacion textual segun la nota media.
     * 
     * <p>Los rangos son:</p>
     * <ul>
     *   <li>9.0 - 10.0: Sobresaliente</li>
     *   <li>7.0 - 8.9: Notable</li>
     *   <li>5.0 - 6.9: Aprobado</li>
     *   <li>0.0 - 4.9: Suspenso</li>
     * </ul>
     * 
     * @return la calificacion textual correspondiente a la nota media
     */
    public String getCalificacion() {
        if (notaMedia >= 9) return "Sobresaliente";
        if (notaMedia >= 7) return "Notable";
        if (notaMedia >= 5) return "Aprobado";
        return "Suspenso";
    }

    @Override
    public String getRol() { return "Alumno"; }
}

