public class EjemploJavadoc {

    /**
     * Calcula el factorial de un numero.
     * 
     * @param n el numero (debe ser >= 0)
     * @return el factorial de n
     * @throws IllegalArgumentException si n es negativo
     * @see #esPar(int)
     */
    public static long factorial(int n) {
        if (n < 0) throw new IllegalArgumentException("n debe ser >= 0");
        if (n <= 1) return 1;
        return n * factorial(n - 1);
    }

    /**
     * Comprueba si un numero es par.
     * 
     * @param n el numero a comprobar
     * @return {@code true} si n es par, {@code false} si es impar
     */
    public static boolean esPar(int n) {
        return n % 2 == 0;
    }
}

