public interface EstrategiaDescuento {
    double calcularDescuento(double precio);
    String getNombre();
}

/**
 * Sin descuento.
 */
public class SinDescuento implements EstrategiaDescuento {
    @Override public double calcularDescuento(double precio) { return 0; }
    @Override public String getNombre() { return "Sin descuento"; }
}

/**
 * Descuento por porcentaje.
 */
public class DescuentoPorcentaje implements EstrategiaDescuento {
    private double porcentaje;
    public DescuentoPorcentaje(double p) { this.porcentaje = p; }
    @Override public double calcularDescuento(double precio) { return precio * porcentaje / 100; }
    @Override public String getNombre() { return "Descuento " + porcentaje + "%"; }
}

/**
 * Descuento fijo en euros.
 */
public class DescuentoFijo implements EstrategiaDescuento {
    private double cantidadFija;
    public DescuentoFijo(double c) { this.cantidadFija = c; }
    @Override public double calcularDescuento(double precio) {
        return Math.min(cantidadFija, precio); // No puede ser mayor que el precio
    }
    @Override public String getNombre() { return "Descuento fijo: " + cantidadFija + " EUR"; }
}

