public interface Forma {
    void dibujar();
    double getArea();
    String getNombre();
}

public class Circulo implements Forma {
    private double radio;
    public Circulo(double r) { this.radio = r; }
    @Override public void dibujar() { System.out.println("Dibujando circulo"); }
    @Override public double getArea() { return Math.PI * radio * radio; }
    @Override public String getNombre() { return "Circulo"; }
}

public class Cuadrado implements Forma {
    private double lado;
    public Cuadrado(double l) { this.lado = l; }
    @Override public void dibujar() { System.out.println("Dibujando cuadrado"); }
    @Override public double getArea() { return lado * lado; }
    @Override public String getNombre() { return "Cuadrado"; }
}

public class Triangulo implements Forma {
    private double base, altura;
    public Triangulo(double b, double h) { this.base = b; this.altura = h; }
    @Override public void dibujar() { System.out.println("Dibujando triangulo"); }
    @Override public double getArea() { return (base * altura) / 2; }
    @Override public String getNombre() { return "Triangulo"; }
}

public class FormaFactory {
    public static Forma crear(String tipo, double... params) {
        return switch (tipo.toLowerCase()) {
            case "circulo" -> new Circulo(params[0]);
            case "cuadrado" -> new Cuadrado(params[0]);
            case "triangulo" -> new Triangulo(params[0], params[1]);
            default -> throw new IllegalArgumentException("Tipo desconocido: " + tipo);
        };
    }

    public static void main(String[] args) {
        Forma[] formas = {
            FormaFactory.crear("circulo", 5),
            FormaFactory.crear("cuadrado", 4),
            FormaFactory.crear("triangulo", 6, 3)
        };
        for (Forma f : formas) {
            f.dibujar();
            System.out.println(f.getNombre() + ": " + f.getArea());
        }
    }
}

public interface EstrategiaFacturacion {
    double calcularImporte(double base);
    String getDescripcion();
}

public class FacturacionNormal implements EstrategiaFacturacion {
    @Override public double calcularImporte(double base) { return base; }
    @Override public String getDescripcion() { return "Normal"; }
}

public class FacturacionConIVA implements EstrategiaFacturacion {
    private double porcentajeIVA;
    public FacturacionConIVA(double iva) { this.porcentajeIVA = iva; }
    @Override public double calcularImporte(double base) { return base * (1 + porcentajeIVA / 100); }
    @Override public String getDescripcion() { return "IVA " + porcentajeIVA + "%"; }
}

public class FacturacionConDescuento implements EstrategiaFacturacion {
    private double porcentajeDescuento;
    public FacturacionConDescuento(double d) { this.porcentajeDescuento = d; }
    @Override public double calcularImporte(double base) { return base * (1 - porcentajeDescuento / 100); }
    @Override public String getDescripcion() { return "Descuento " + porcentajeDescuento + "%"; }
}

public class Factura {
    private String cliente;
    private double baseImponible;
    private EstrategiaFacturacion estrategia;

    public Factura(String cliente, double base, EstrategiaFacturacion e) {
        this.cliente = cliente;
        this.baseImponible = base;
        this.estrategia = e;
    }

    public void setEstrategia(EstrategiaFacturacion e) { this.estrategia = e; }
    public double getImporteTotal() { return estrategia.calcularImporte(baseImponible); }

    @Override
    public String toString() {
        return cliente + " | Base: " + baseImponible + " | " + estrategia.getDescripcion()
             + " | Total: " + String.format("%.2f", getImporteTotal()) + " EUR";
    }

    public static void main(String[] args) {
        Factura[] facturas = {
            new Factura("Ana", 100, new FacturacionNormal()),
            new Factura("Carlos", 200, new FacturacionConIVA(21)),
            new Factura("Maria", 150, new FacturacionConDescuento(15))
        };
        for (Factura f : facturas) System.out.println(f);
    }
}
